```sql
alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create or replace function public.is_friend(target_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.friendships f
    where (f.requester_id = auth.uid() and f.addressee_id = target_id)
       or (f.requester_id = target_id and f.addressee_id = auth.uid())
    and f.status = 'accepted'
  );
$$;

create or replace function public.enforce_friendship_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'pending' then
      raise exception 'new friendship requests must be pending';
    end if;
    if new.requester_id = new.addressee_id then
      raise exception 'cannot send a friend request to yourself';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if new.requester_id <> old.requester_id or new.addressee_id <> old.addressee_id then
      raise exception 'friendship ids cannot be changed';
    end if;
    if old.status <> 'pending' then
      raise exception 'only pending requests can be accepted';
    end if;
    if new.status <> 'accepted' then
      raise exception 'invalid status transition';
    end if;
    if new.addressee_id <> auth.uid() then
      raise exception 'only the addressee can accept a request';
    end if;
    return new;
  end if;

  return new;
end;
$$;

create trigger friendships_enforce_update
  before insert or update on public.friendships
  for each row execute function public.enforce_friendship_update();

create policy "friendships_select_participant"
  on public.friendships for select
  to authenticated
  using (requester_id = auth.uid() or addressee_id = auth.uid());

create policy "friendships_insert_requester"
  on public.friendships for insert
  to authenticated
  with check (requester_id = auth.uid() and status = 'pending');

create policy "friendships_update_addressee"
  on public.friendships for update
  to authenticated
  using (addressee_id = auth.uid() and status = 'pending')
  with check (addressee_id = auth.uid() and status = 'accepted');

create policy "friendships_delete_participant"
  on public.friendships for delete
  to authenticated
  using (requester_id = auth.uid() or addressee_id = auth.uid());

create policy "posts_select_audience"
  on public.posts for select
  to anon, authenticated
  using (
    audience = 'public'
    or (authenticated and (author_id = auth.uid() or public.is_friend(author_id)))
  );

create policy "posts_insert_own"
  on public.posts for insert
  to authenticated
  with check (author_id = auth.uid());

create policy "posts_update_own"
  on public.posts for update
  to authenticated
  using (author_id = auth.uid())
  with check (author_id = auth.uid());

create policy "posts_delete_own"
  on public.posts for delete
  to authenticated
  using (author_id = auth.uid());

revoke all on public.friendships from anon;
revoke all on public.posts from anon;
revoke all on public.friendships from authenticated;
revoke all on public.posts from authenticated;

grant select on public.friendships to authenticated;
grant insert, update, delete on public.friendships to authenticated;
grant select, insert, update, delete on public.posts to authenticated;
grant all on public.friendships to service_role;
grant all on public.posts to service_role;
```

