create or replace function public.prevent_request_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.status <> 'open' then
      raise exception 'new requests must be open';
    end if;
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if new.id <> old.id
       or new.unit_id <> old.unit_id
       or new.created_by <> old.created_by
       or new.description <> old.description then
