```sql
alter table public.auctions enable row level security;
alter table public.bids enable row level security;

create policy "Authenticated users can view all auctions"
on public.auctions for select to authenticated
using (true);

create policy "Users can view their own bids"
on public.bids for select to authenticated
using (bidder_id = auth.uid());

create policy "Sellers can view bids on their auctions"
on public.bids for select to authenticated
using (exists (select 1 from public.auctions a where a.id = bids.auction_id and a.seller_id = auth.uid()));

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_caller uuid := auth.uid();
  v_auction public.auctions%rowtype;
  v_current_highest numeric;
  v_min_increment numeric;
begin
  if v_caller is null then
    raise exception 'Not authenticated';
  end if;

  select * into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'Auction not found';
  end if;

  if v_auction.ends_at < now() then
    raise exception 'Auction has ended';
  end if;

  if v_auction.seller_id = v_caller then
    raise exception 'Cannot bid on your own auction';
  end if;

  v_min_increment := coalesce(v_auction.min_increment, 10);
  v_current_highest := coalesce(v_auction.highest_bid, 0);

  if p_amount <= v_current_highest then
    raise exception 'Bid must be higher than current highest bid';
  end if;

  if v_current_highest is null then
    if p_amount <= v_auction.starting_price then
      raise exception 'Bid must be at least the starting price';
    end if;
  else
    if p_amount < v_current_highest + v_min_increment then
      raise exception 'Bid must be at least % above current highest bid', v_current_highest + v_min_increment;
    end if;
  end if;

  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, v_caller, p_amount);

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_caller
  where id = p_auction_id;

  return p_amount;
end;
$$;

