create or replace function public.can_enroll_in_class(p_class_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.classes c
    where c.id = p_class_id
      and c.instructor_id <> auth.uid()
      and (
        select count(*)
        from public.class_spots s
        where s.class_id = c.id
          and s.status = 'enrolled'
      ) < c.capacity
  );
$$;

create or replace function public.class_spot_enforced_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.user_id <> auth.uid() then
      raise exception 'class spot user_id must match authenticated user';
    end if;
    if new.status not in ('enrolled', 'waitlisted') then
      raise exception 'invalid class spot status';
    end if;
    if not public.can_enroll_in_class(new.class_id) then
      raise exception 'cannot enroll in this class';
    end if;
    return new;
  elsif tg_op = 'UPDATE' then
    if new.class_id <> old.class_id or new.user_id <> old.user_id then
      raise exception 'class spot class_id and user_id cannot change';
    end if;
    if old.status = 'enrolled' then
      raise exception 'enrolled spots cannot be updated';
    end if;
    if new.status <> 'enrolled' then
      raise exception 'waitlisted spot can only move to enrolled';
    end if;
    if not public.can_enroll_in_class(old.class_id) then
      raise exception 'no room to enroll in this class';
    end if;
    return new;
  else
    return new;
  end if;
end;
$$;

